style.css:
@-moz-document domain("youtube.com") {
/* --- 1. Global Backgrounds --- */
    html, [dark], ytd-app, #master-container {
        background-color: #000000 !important;
        --yt-spec-base-background: #000000 !important;
        --yt-spec-brand-background-primary: #000000 !important;
        --yt-spec-menu-background: #0a0a0a !important;
        --yt-spec-raised-background: #0a0a0a !important;
        --yt-spec-text-primary: #ffffff !important;
    }

    /* --- 2. Header & Search --- */
    #masthead-container, ytd-masthead {
        background: rgba(0, 0, 0, 0.95) !important;
        backdrop-filter: blur(10px);
        border-bottom: 1px solid #222;
    }

    #search-form #container {
        background-color: #111 !important;
        border: 1px solid #333 !important;
        border-radius: 12px !important;
        box-shadow: inset 0 1px 4px rgba(0,0,0,0.5);
    }

    /* --- 3. Video Cards & Interactions --- */
    ytd-rich-item-renderer, ytd-video-renderer, ytd-grid-video-renderer {
        transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1);
    }

    ytd-rich-item-renderer:hover, ytd-video-renderer:hover {
        transform: scale(1.02);
        z-index: 10;
    }

    ytd-thumbnail, #thumbnail {
        border-radius: 12px !important;
        overflow: hidden;
        box-shadow: 0 4px 20px rgba(0,0,0,0.6);
    }

    /* --- 4. The Neon Pink Accents --- */
    .ytp-play-progress {
        background: #ff0055 !important;
        box-shadow: 0 0 12px #ff0055, 0 0 20px #ff0055;
    }

    .ytp-scrubber-button {
        background: #fff !important;
        box-shadow: 0 0 15px #ff0055;
        transform: scale(1.2);
    }

    .ytp-swatch-background-color {
        background-color: #ff0055 !important;
    }

    /* --- 5. Sidebar & Guide --- */
    #guide-content, ytd-mini-guide-renderer {
        background: #000000 !important;
        border-right: 1px solid #222;
    }

    ytd-guide-entry-renderer:hover {
        background-color: #1a1a1a !important;
        border-radius: 10px;
    }

    /* --- 6. Scrollbars (Chrome/Edge/Webkit) --- */
    ::-webkit-scrollbar {
        width: 10px;
        background: #000;
    }
    ::-webkit-scrollbar-track {
        background: #000;
    }
    ::-webkit-scrollbar-thumb {
        background: #333;
        border-radius: 5px;
        border: 2px solid #000;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #ff0055;
    }
}
